-- PT119-S3-Q1. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT119-S3-Q1$batch03$ AND q.stimulus=$batch03$Sambar deer are physically incapable of digesting meat. Yet sambar deer have been reported feeding on box turtles after killing them.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, best resolves the discrepancy above?$batch03$ AND q.correct_choice=$batch03$A$batch03$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT119-S3-Q1$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT119-S3-Q1$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Sambar deer cannot digest meat.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$They have been seen eating box turtles after killing them?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$A turtle is not all meat. If the deer eat a part they can digest, there is no conflict.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a non-meat part of the turtle the deer eat.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT119-S3-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$The deer eat only the bony shells. That is not meat, so they can feed on turtles without digesting meat.$batch03$), ($batch03$B$batch03$, $batch03$Killing turtles by accident explains the killing, not the eating.$batch03$), ($batch03$C$batch03$, $batch03$How often it happens does not explain how a deer that cannot digest meat eats a turtle at all.$batch03$), ($batch03$D$batch03$, $batch03$Competition for food might explain killing turtles. It does not explain eating them.$batch03$), ($batch03$E$batch03$, $batch03$Turtles being slow explains how deer catch them, not why they eat them.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT119-S3-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
